CREATE TABLE IF NOT EXISTS cms_cache_metrics(id INTEGER PRIMARY KEY AUTOINCREMENT,metric_key TEXT NOT NULL UNIQUE,hits INTEGER NOT NULL DEFAULT 0,misses INTEGER NOT NULL DEFAULT 0,evictions INTEGER NOT NULL DEFAULT 0,last_hit_at TEXT,last_miss_at TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_performance_samples(id INTEGER PRIMARY KEY AUTOINCREMENT,sample_key TEXT NOT NULL,path TEXT NOT NULL,duration_ms INTEGER NOT NULL,memory_peak INTEGER NOT NULL,cache_status TEXT NOT NULL DEFAULT 'none',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
